"use strict";
const fs = require("fs");
const TAU = Math.PI * 2;
let FAILED = 0;
function ok(cond, msg) {
  if (!cond) { FAILED++; console.error("FAIL:", msg); }
}

// ---------- stubs de DOM ----------
function makeFake() {
  const target = function () {};
  const proxy = new Proxy(target, {
    get(t, k) {
      if (k === "canvas") return canvasEl;
      if (k === Symbol.toPrimitive) return () => 0;
      if (k === "then" || k === Symbol.toPrimitive || typeof k === "symbol") return undefined;
      return proxy;
    },
    set() { return true; }
  });
  return proxy;
}
const ctx2d = makeFake();
const canvasEl = {
  width: 0, height: 0,
  getContext: () => ctx2d,
  addEventListener: () => {}
};
const hudEl = { textContent: "" };
global.window = {
  innerWidth: 1280, innerHeight: 720, devicePixelRatio: 1,
  addEventListener: () => {}
};
global.document = {
  getElementById: (id) => (id === "cv" ? canvasEl : hudEl),
  addEventListener: () => {}
};
global.addEventListener = () => {};
global.performance = { now: () => Date.now() };
let rafCb = null;
global.requestAnimationFrame = (cb) => { rafCb = cb; return 1; };

// ---------- carregar o script do index.html ----------
const html = fs.readFileSync(process.argv[2] || "index.html", "utf8");
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if (!m) { console.error("FAIL: script tag não encontrada"); process.exit(1); }
(0, eval)(m[1]);

const B = global.window.__bench;
ok(!!B, "window.__bench existe");
ok(typeof B.getState === "function", "getState é função");
ok(typeof B.step === "function", "step é função");

const s0 = B.getState();
ok(Object.keys(s0).sort().join(",") === "balls,poly,t", "keys top-level: " + Object.keys(s0));
ok(Object.keys(s0.poly).sort().join(",") === "angle,cx,cy,n,periodSec,radius", "keys poly");
ok(s0.poly.n === 9, "poly.n===9");
ok(s0.poly.radius === 260, "poly.radius===260");
ok(s0.poly.periodSec === 7, "poly.periodSec===7");
ok(Math.abs(s0.poly.angle - s0.t * TAU / 7) < 1e-12, "angle == t*TAU/7");
ok(Math.abs(s0.poly.cx - 640) < 1e-9 && Math.abs(s0.poly.cy - 360) < 1e-9, "centro do canvas");
ok(s0.balls.length === 13, "13 bolas");
ok(s0.balls.every(b => Object.keys(b).sort().join(",") === "id,r,vx,vy,x,y", "keys bola"));
ok(s0.balls.every((b, i) => b.id === i), "ids 0..12 em ordem");
ok(s0.balls.every(b => b.r === 14), "raio 14");
ok(s0.balls.every(b => isFinite(b.x) && isFinite(b.y) && isFinite(b.vx) && isFinite(b.vy)), "finitos");

// estado inicial: proximidade ao centro e velocidade nula
ok(s0.balls.every(b => Math.hypot(b.x - 640, b.y - 360) <= 100), "bolas começam próximas do centro");
ok(s0.balls.every(b => b.vx === 0 && b.vy === 0), "velocidade inicial nula");

function insideCheck(s, label) {
  for (const b of s.balls) {
    for (let i = 0; i < 9; i++) {
      const am = s.poly.angle + (i + 0.5) * TAU / 9;
      const d = -(b.x - s.poly.cx) * Math.cos(am) - (b.y - s.poly.cy) * Math.sin(am);
      if (!(d >= b.r - 1e-6)) { ok(false, `${label}: bola ${b.id} fora do poligono (side ${i}, d=${d})`); return; }
    }
  }
  for (let i = 0; i < 13; i++)
    for (let j = i + 1; j < 13; j++) {
      const a = s.balls[i], c = s.balls[j];
      const dd = Math.hypot(a.x - c.x, a.y - c.y);
      if (!(dd >= a.r + c.r - 1e-6)) { ok(false, `${label}: sobreposição ${i}-${j} (d=${dd})`); return; }
    }
}

// vários passos com dt variados (incl. grandes, p/ stress dos subpassos)
const dts = [0.1, 0.5, 0.25, 1, 2, 0.016, 3, 0.123456, 0.7, 5];
let prevT = s0.t;
for (let k = 0; k < dts.length; k++) {
  const dt = dts[k];
  B.step(dt);
  const s = B.getState();
  ok(Math.abs((s.t - prevT) - dt) < 1e-9, `t avança exatamente dt (step ${dt})`);
  prevT = s.t;
  ok(Math.abs(s.poly.angle - s.t * TAU / 7) < 1e-9, "angle consistente (" + k + ")");
  insideCheck(s, "step " + k);
  ok(s.balls.every(b => isFinite(b.x) && isFinite(b.y) && isFinite(b.vx) && isFinite(b.vy)), "finitos (" + k + ")");
}

// determinismo: passo grande + passo pequeno devem ser estáveis a longo prazo
for (let i = 0; i < 300; i++) B.step(i % 7 === 0 ? 2 : 1 / 60);
const sL = B.getState();
insideCheck(sL, "long run");

// a simulação está viva? (bolas no fundo, com velocidades variadas)
console.log("t =", sL.t.toFixed(3));
console.log("exemplo:", JSON.stringify(sL.balls[0]), JSON.stringify(sL.balls[7]));
const maxY = Math.max(...sL.balls.map(b => b.y));
ok(maxY > 500, "bolas caem (gravity ativa): maxY=" + maxY);
const anyMoving = sL.balls.some(b => Math.hypot(b.vx, b.vy) > 0);
ok(anyMoving, "velocidades não triviais");

if (FAILED === 0) console.log("TODOS OS TESTES PASSARAM");
else { console.error(FAILED + " falhas"); process.exit(1); }

