function hardPair(a, b) {
  const dx = b.x - a.x, dy = b.y - a.y;
  const minD = a.r + b.r;
  const d2 = dx * dx + dy * dy;
  if (d2 >= minD * minD) return false;
  const d = Math.sqrt(d2);
  const nx = d > 1e-9 ? dx / d : 1;
  const ny = d > 1e-9 ? dy / d : 0;
  const push = (minD - d) / 2;
  a.x -= nx * push; a.y -= ny * push;
  b.x += nx * push; b.y += ny * push;
  return true;
}

// Garantia forte: "as bolas nunca saem do polígono nem se sobrepõem".
// Alternado pares -> paredes até convergir (parede sempre resolvida por
// último, já que é a restrição inegociável).
function enforce() {
  for (let it = 0; it < 32; it++) {
    let viol = false;
    for (let i = 0; i < balls.length; i++)
      for (let j = i + 1; j < balls.length; j++)
        if (hardPair(balls[i], balls[j])) viol = true;
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];
      if (!inPoly(b.x, b.y)) { relocate(b); viol = true; continue; }
      const cb = closestBoundary(b.x, b.y);
      const d = Math.sqrt(cb.d2);
      if (d < b.r) {
        if (d > 1e-9) { b.x += (b.x - cb.qx) / d * (b.r - d); b.y += (b.y - cb.qy) / d * (b.r - d); }
        else { const n = nOut(cb.i); b.x -= n.x * b.r; b.y -= n.y * b.r; }
        viol = true;
      }
    }
    if (!viol) break;
  }
}

